import{_ as s,C as i,o as t,c as n,a2 as r,b as l,w as o,a as d,E as c,a3 as h}from"./chunks/framework.Dd_iHz3e.js";const b=JSON.parse('{"title":"14.2 Architecture Styles: Monolith vs Modular vs Serverless","description":"","frontmatter":{},"headers":[],"relativePath":"system-design/14.2-architecture-styles.md","filePath":"system-design/14.2-architecture-styles.md"}'),u={name:"system-design/14.2-architecture-styles.md"};function g(p,e,m,v,A,f){const a=i("Mermaid");return t(),n("div",null,[e[1]||(e[1]=r('<h1 id="_14-2-architecture-styles-monolith-vs-modular-vs-serverless" tabindex="-1">14.2 Architecture Styles: Monolith vs Modular vs Serverless <a class="header-anchor" href="#_14-2-architecture-styles-monolith-vs-modular-vs-serverless" aria-label="Permalink to &quot;14.2 Architecture Styles: Monolith vs Modular vs Serverless&quot;">​</a></h1><h2 id="_1-plain-english-overview" tabindex="-1">1. Plain English Overview <a class="header-anchor" href="#_1-plain-english-overview" aria-label="Permalink to &quot;1. Plain English Overview&quot;">​</a></h2><p>An architectural style defines how system components are partitioned, deployed, and communicate with each other—ranging from a single unified codebase (monolith) to decoupled independent network services (microservices) or ephemeral cloud functions (serverless).</p><hr><h2 id="_2-usage-in-cooking-nexus" tabindex="-1">2. Usage in Cooking Nexus <a class="header-anchor" href="#_2-usage-in-cooking-nexus" aria-label="Permalink to &quot;2. Usage in Cooking Nexus&quot;">​</a></h2><p>Cooking Nexus uses a <strong>Hybrid Modular Monolith + Serverless Edge Architecture</strong>:</p><ul><li><strong>Core Ingestion &amp; Auth</strong>: Structured as a modular Express monolith ([server.js](file:///Users/avishjain/avishjain9-repos/26-cooking-nexus/server.js)) with distinct controllers, services, and Mongoose models.</li><li><strong>AI Inference</strong>: Delegated to serverless edge functions ([supabase/functions/chef-ai/index.ts](file:///Users/avishjain/avishjain9-repos/26-cooking-nexus/27-kitchen-companion-pro/supabase/functions/chef-ai/index.ts)) to stream Gemini 3 Flash tokens without tying up Express threads.</li><li><strong>Frontend SPA</strong>: React 18 single-page application served statically via CDN.</li></ul><hr><h2 id="_3-architecture-topology-diagram" tabindex="-1">3. Architecture Topology Diagram <a class="header-anchor" href="#_3-architecture-topology-diagram" aria-label="Permalink to &quot;3. Architecture Topology Diagram&quot;">​</a></h2>',9)),(t(),l(h,null,{default:o(()=>[c(a,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20subgraph%20ClientLayer%20%5B%22Client%20%26%20Sensor%20Layer%22%5D%0A%20%20%20%20%20%20%20%20SPA%5BReact%2018%20SPA%5D%0A%20%20%20%20%20%20%20%20Sensors%5BKitchen%20Range%20Cameras%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20ServerlessEdge%20%5B%22Serverless%20Edge%20Tier%22%5D%0A%20%20%20%20%20%20%20%20EdgeAI%5BSupabase%20Deno%20Edge%20chef-ai%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20ModularMonolith%20%5B%22Modular%20Ingestion%20Monolith%22%5D%0A%20%20%20%20%20%20%20%20Gateway%5BExpress%205%20Server%5D%0A%20%20%20%20%20%20%20%20AuthMod%5BAuth%20Controller%20%26%20JWT%5D%0A%20%20%20%20%20%20%20%20VisionMod%5BSafety%20Controller%20%26%20Vision%20Svc%5D%0A%20%20%20%20%20%20%20%20MemberMod%5BMember%20Profile%20Controller%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20DataLayer%20%5B%22Persistence%20Tier%22%5D%0A%20%20%20%20%20%20%20%20MongoDB%5B(MongoDB%20Cluster)%5D%0A%20%20%20%20end%0A%0A%20%20%20%20SPA%20--%3E%7CSSE%20Streaming%20Token%20Requests%7C%20EdgeAI%0A%20%20%20%20SPA%20--%3E%7CMagic%20Link%20%2F%20Profile%20Requests%7C%20Gateway%0A%20%20%20%20Sensors%20--%3E%7CPOST%20%2Fapi%2Fvision%20Telemetry%7C%20Gateway%0A%0A%20%20%20%20Gateway%20--%3E%20AuthMod%20%26%20VisionMod%20%26%20MemberMod%0A%20%20%20%20VisionMod%20%26%20AuthMod%20%26%20MemberMod%20--%3E%20MongoDB%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<hr><h2 id="_4-architectural-alternatives-comparison" tabindex="-1">4. Architectural Alternatives Comparison <a class="header-anchor" href="#_4-architectural-alternatives-comparison" aria-label="Permalink to &quot;4. Architectural Alternatives Comparison&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Architectural Style</th><th>Development Velocity</th><th>Operational Complexity</th><th>Network Latency</th><th>Fault Isolation</th><th>Fit for Cooking Nexus</th></tr></thead><tbody><tr><td><strong>Hybrid Modular (Chosen)</strong></td><td>High (Single repo, shared types)</td><td>Low (Single deployment target)</td><td>Zero IPC overhead</td><td>Moderate (Edge separates AI)</td><td>Optimal for current scale</td></tr><tr><td><strong>Pure Microservices</strong></td><td>Low (Heavy boilerplate)</td><td>Extreme (K8s, service mesh)</td><td>High (Inter-service RPC hops)</td><td>High (Isolated blast radius)</td><td>Overkill for early stage</td></tr><tr><td><strong>Pure Serverless (Lambda)</strong></td><td>Moderate (Cold start delays)</td><td>Moderate (Vendor IAM rules)</td><td>Unpredictable cold starts</td><td>High per function</td><td>Bad for continuous vision sockets</td></tr><tr><td><strong>Hexagonal / Clean Arch</strong></td><td>Slow (Extreme abstraction)</td><td>High (Interfaces, ports/adapters)</td><td>Minimal</td><td>High</td><td>Excessive ceremony for CRUD</td></tr></tbody></table><hr><h2 id="_5-trade-offs-accepted" tabindex="-1">5. Trade-offs Accepted <a class="header-anchor" href="#_5-trade-offs-accepted" aria-label="Permalink to &quot;5. Trade-offs Accepted&quot;">​</a></h2><ul><li><strong>Monolith Shared Process</strong>: If an uncaught exception crashes the Express process, both auth and vision ingestion go down simultaneously. This was accepted because Node process managers (<code>pm2</code> or Docker restart policies) reboot the process in &lt;1 second.</li></ul><hr><h2 id="_6-what-breaks-first-at-scale" tabindex="-1">6. What Breaks First at Scale? <a class="header-anchor" href="#_6-what-breaks-first-at-scale" aria-label="Permalink to &quot;6. What Breaks First at Scale?&quot;">​</a></h2><ul><li><strong>At 10x</strong>: Shared memory saturation if image frames are buffered in RAM inside the Node process.</li><li><strong>At 100x</strong>: Deployment lock-in: updating the member profile route requires redeploying the vision ingestion server.</li><li><strong>At 1,000x</strong>: Inter-module database contention: heavy vision writes compete with member authentication reads on the same MongoDB instance.</li></ul><hr><h2 id="_7-senior-engineer-decomposition-plan" tabindex="-1">7. Senior Engineer Decomposition Plan <a class="header-anchor" href="#_7-senior-engineer-decomposition-plan" aria-label="Permalink to &quot;7. Senior Engineer Decomposition Plan&quot;">​</a></h2><p>When monthly active kitchens exceed 50,000, carve out the <code>/api/vision</code> ingestion pipeline into a standalone Go microservice using gRPC, leaving Express to manage user accounts and social feeds.</p><hr><h2 id="_8-spoken-interview-answer-30-seconds" tabindex="-1">8. Spoken Interview Answer (30 Seconds) <a class="header-anchor" href="#_8-spoken-interview-answer-30-seconds" aria-label="Permalink to &quot;8. Spoken Interview Answer (30 Seconds)&quot;">​</a></h2><p>&quot;We chose a hybrid architecture: a modular Express monolith for core authentication and vision ingestion, paired with serverless Deno edge functions for streaming AI tokens. This gives us the high developer velocity and zero-IPC simplicity of a monolith, while completely isolating heavy, long-lived LLM streaming connections from our core safety telemetry server. We avoid the operational tax of microservices until scaling demands independent service autoscaling.&quot;</p>',15))])}const _=s(u,[["render",g]]);export{b as __pageData,_ as default};
